function toast(msg,bad=false){const e=$('toast');if(!e)return;clearTimeout(toast.t);const message=String(msg??'');e.className='toast show'+(bad?' bad':'');e.replaceChildren();const body=document.createElement('div');body.className='toast-message';body.textContent=message;const actions=document.createElement('div');actions.className='toast-actions';const copy=document.createElement('button');copy.type='button';copy.className='toast-btn';copy.textContent='Copy';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy',1600)}catch(_){const ta=document.createElement('textarea');ta.value=message;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');copy.textContent='Copied'}finally{ta.remove();setTimeout(()=>copy.textContent='Copy',1600)}}});const close=document.createElement('button');close.type='button';close.className='toast-btn';close.textContent='Close';close.addEventListener('click',()=>{clearTimeout(toast.t);e.className='toast'});actions.append(copy,close);e.append(body,actions);if(!bad){toast.t=setTimeout(()=>e.className='toast',8000)}}
