function renderSites(rows){const root=$('sitesGrid');if(!root)return;const seen=new Set(),unique=rows.filter(s=>{const d=String(s.domain||'').toLowerCase();if(!d||seen.has(d))return false;seen.add(d);return true});root.innerHTML=unique.length?`<div class="site-list-head"><span>Website</span><span>Hosting account</span><span>PHP</span><span>DNS / SSL</span><span>Status</span><span>Actions</span></div>`+unique.map(s=>`<article class="site-list-row"><span class="site-domain-cell"><button type="button" class="site-link-button" data-site-edit="${esc(s.domain)}"><i class="site-dot"></i>${esc(s.domain)}</button><small title="${esc(s.document_root)}">${s.kind==='subdomain'?`Subdomain of ${esc(s.parent_domain||'parent')} · `:''}${s.document_root?esc(s.document_root):'Live vhost not currently detected'}</small></span><span><small>Hosting account</small><b>${esc(accountLabel(s.username))}</b></span><span><small>PHP</small><b>${esc(s.php_version||'unknown')}</b></span><span><small>DNS / SSL</small><b>${esc(s.dns||'external')} · ${esc(s.ssl||'unknown')}</b></span><span><em class="status-pill ${s.status==='active'?'active':'failed'}" title="${esc(s.status_reason||'')}">${esc(siteStatusLabel(s.status))}</em></span><span class="row-actions">${s.status==='missing'?`<button class="table-btn" data-site-repair="${esc(s.domain)}">Repair config</button>`:`<button class="table-btn" data-site-edit="${esc(s.domain)}">Edit</button>`}<button class="table-btn danger compact-danger" data-site-delete="${esc(s.domain)}">Delete</button></span></article>`).join(''):'<article class="panel-card empty">No named website vhosts or recorded primary domains were found on this server.</article>'}
function renderPhp(rows){const root=$('phpSites');if(!root)return;const versions=state.phpRuntimes.length?state.phpRuntimes.filter(x=>x.fpm).map(x=>x.version):['8.5','8.4','8.3','8.2'];root.innerHTML=`<div class="tr th"><span>Website</span><span>Hosting account</span><span>Current</span><span>Change version</span></div>`+(rows.length?rows.map(s=>`<div class="tr"><span><b>${esc(s.domain)}</b></span><span>${esc(accountLabel(s.username))}</span><span><em class="php-badge">PHP ${esc(s.php_version||'unknown')}</em></span><span>${s.status==='active'?`<select class="php-select" data-domain="${esc(s.domain)}">${versions.map(v=>`<option ${v===s.php_version?'selected':''}>${v}</option>`).join('')}</select>`:'<small>Unavailable until live vhost is detected</small>'}</span></div>`).join(''):`<div class="empty">No websites configured.</div>`)}
function renderInventoryDiagnostics(inv,accounts,sites){const badge=$('inventorySourceBadge'),summary=$('inventoryDiscoverySummary'),warn=$('inventoryWarnings');if(!badge||!summary||!warn)return;const d=inv.diagnostics||{},warnings=inv.warnings||[],env=d.environment||{},counts=d.counts||{};const liveSource=String(inv.source||'').startsWith('live-host');badge.textContent=liveSource?(String(inv.source).includes('+recorded')?'LIVE HOST · RECONCILED':'LIVE HOST'):'NOT LIVE';badge.className='status-pill '+(liveSource?'active':'failed');const effective=d.nginx_effective_config===true?'effective nginx -T active config':'conventional nginx files';const blocks=d.nginx_active_server_blocks??'—';const paths=(d.nginx_scan_paths||[]).join(', '),stack=[env.control_panel&&env.control_panel!=='none'?env.control_panel:null,env.web_server&&env.web_server!=='unknown'?env.web_server:null].filter(Boolean).join(' + ')||'generic Linux hosting';summary.textContent=`${stack} · detected ${sites.length} website${sites.length===1?'':'s'}, ${accounts.length} hosting account${accounts.length===1?'':'s'} · ${effective} · active server blocks ${blocks}${paths?' · scanned '+paths:''}`;warn.innerHTML=warnings.length?'<b>Discovery notices:</b> '+warnings.map(esc).join(' · '):'<span class="status-pill active">No discovery warnings</span>';}
function renderTerminationPlan(plan){const root=$('accountTerminationPlan'),button=$('accountDeleteForm')?.querySelector('button[type="submit"]'),fingerprint=$('accountDeletePlanFingerprint');if(!root)return;const groups=[['Websites',plan.websites],['DNS zones',plan.dns_zones],['Databases',plan.databases],['Mailboxes',plan.mailboxes],['Certificates',plan.certificates],['SFTP',plan.sftp_accounts],['Applications',[...(plan.applications||[]),...(plan.app_installs||[]),...(plan.deployments||[])]],['Cron records',plan.cron_jobs],['Backups retained',plan.backups]];const resources=groups.filter(x=>(x[1]||[]).length).map(([name,rows])=>`<div class="termination-resource"><b>${esc(name)}</b><small>${rows.map(esc).join('<br>')}</small></div>`).join('');const blockers=(plan.blockers||[]).map(x=>`<li>${esc(x)}</li>`).join('');const retained=(plan.retained||[]).map(x=>`<li>${esc(x)}</li>`).join('');root.innerHTML=`<div class="termination-status ${plan.ready?'ready':'blocked'}"><b>${plan.ready?'READY FOR CONFIRMATION':'TERMINATION BLOCKED'}</b><span>${esc(plan.status||'unknown')} · ${esc(plan.home_directory||'home not discovered')}</span></div>${resources||'<div class="empty">No separately tracked owned resources were discovered.</div>'}${blockers?`<div class="termination-alert"><b>Resolve before termination</b><ul>${blockers}</ul></div>`:''}${retained?`<div class="termination-retained"><b>Retained after termination</b><ul>${retained}</ul></div>`:''}<details><summary>Discovery coverage</summary><ul>${(plan.coverage_warnings||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`;if(fingerprint)fingerprint.value=plan.ready?(plan.fingerprint||''):'';if(button)button.disabled=!plan.ready}
function selectedAccounts(){return [...document.querySelectorAll('input[data-account-select]:checked')].map(x=>x.value)}
function renderAccounts(rows){const root=$('accountsTable');if(!root)return;const opts=a=>state.packages.length?state.packages.map(p=>`<option value="${esc(p.name)}" ${p.name===a.package?'selected':''}>${esc(p.name)}</option>`).join(''):`<option>${esc(a.package||'Detected')}</option>`;root.innerHTML=`<div class="tr th account-tr account-tr-641"><span><input type="checkbox" id="accountSelectAll" aria-label="Select all"></span><span>Hosting account</span><span>Primary domain / owner</span><span>Package</span><span>Status</span><span>Actions</span></div>`+(rows.length?rows.map(a=>`<div class="tr account-tr account-tr-641"><span><input type="checkbox" data-account-select value="${esc(a.username)}" aria-label="Select ${esc(a.username)}"></span><span><b>${esc(accountLabel(a))}</b><small>${esc(a.username)}${a.reseller?' · reseller '+esc(a.reseller):''}</small></span><span>${esc(a.primary_domain||'—')}<small>${esc(a.owner||'root')} · PPanel ${a.ppanel_configured?'ready':'not configured'}</small></span><span><select class="account-package-select" data-account-package="${esc(a.username)}">${opts(a)}</select></span><span><em class="status-pill ${esc(a.status)}">${esc(a.status)}</em></span><span class="row-actions"><button class="table-btn" data-account-edit="${esc(a.username)}">Edit</button><button class="table-btn" data-ppanel-access="${esc(a.username)}" data-ppanel-domain="${esc(a.primary_domain||'')}">${a.ppanel_configured?'Reset PPanel':'Set PPanel access'}</button><button class="table-btn" data-account="${esc(a.username)}" data-account-action="${a.status==='suspended'?'unsuspend':'suspend'}">${a.status==='suspended'?'Unsuspend':'Suspend'}</button>${a.status==='suspended'?`<button class="table-btn danger compact-danger" data-account-delete="${esc(a.username)}">Delete</button>`:''}</span></div>`).join(''):`<div class="empty">No hosting accounts yet.</div>`);updateBulkCount()}
function updateBulkCount(){const n=selectedAccounts().length;if($('accountBulkCount'))$('accountBulkCount').textContent=`${n} selected`;const all=$('accountSelectAll'),checks=[...document.querySelectorAll('input[data-account-select]')];if(all)all.checked=checks.length>0&&checks.every(x=>x.checked)}
async function openAccountEditor(username){const d=await api(`account-detail&username=${encodeURIComponent(username)}`),a=d.account||{},f=$('accountEditForm');if(!f)return;$('accountEditUsername').value=username;$('accountEditLabel').textContent=username;for(const k of ['primary_domain','owner','reseller','notes','shell_policy'])if(f.elements[k])f.elements[k].value=a[k]??(k==='owner'?'root':k==='shell_policy'?'none':'');const h=d.account_health||{};$('accountHealthPanel').innerHTML=`<div class="termination-summary"><span><b>${esc(h.status||a.status||'unknown')}</b><small>Account status</small></span><span><b>${esc(h.site_count??0)}</b><small>Websites</small></span><span><b>${esc(h.shell||'—')}</b><small>Live shell</small></span><span><b>${h.managed?'Managed':'Discovered'}</b><small>Host identity</small></span></div>`;const hist=d.history||[];$('accountHistoryPanel').innerHTML=hist.length?`<div class="tr th"><span>Time</span><span>Actor</span><span>Event</span></div>`+hist.slice(0,20).map(x=>`<div class="tr"><span>${esc(x.time||'')}</span><span>${esc(x.actor||'')}</span><span>${esc(x.message||x.type||'')}</span></div>`).join(''):'<div class="empty">No recent account history.</div>';openModal('accountEdit')}

function renderConfigFiles(){
 const root=$('configFilesTable'),common=$('configCommonFiles');if(!root||!common)return;
 const q=String($('configFileSearch')?.value||'').trim().toLowerCase(),selected=$('configFileId')?.value||'';
 const matches=x=>{const category=String(x.category||x.family||'');const catOK=configCategory==='all'||(configCategory==='advanced'?x.kind==='vhost':category===configCategory);const hay=[x.label,x.path,x.family,x.category,x.service,x.description].join(' ').toLowerCase();return catOK&&(!q||hay.includes(q))};
 const commonRows=state.configFiles.filter(x=>x.common).slice(0,6);
 common.innerHTML=commonRows.length?commonRows.map(x=>`<button type="button" class="config-common-card ${selected===x.id?'active':''}" data-config-open="${esc(x.id)}"><span class="config-common-icon">${x.family==='php'?'PHP':x.family==='bind'?'DNS':'WEB'}</span><span><b>${esc(x.label)}</b><small>${esc(x.description||x.path)}</small></span><em>${esc(x.service||'config')}</em></button>`).join(''):'<div class="empty">No common configuration files are installed on this host.</div>';
 const rows=state.configFiles.filter(matches);if($('configFileCount'))$('configFileCount').textContent=`${rows.length} file${rows.length===1?'':'s'}`;
 root.innerHTML=rows.length?rows.map(x=>`<button type="button" class="config-file-row ${selected===x.id?'active':''}" data-config-open="${esc(x.id)}"><span class="config-file-main"><b>${esc(x.label)}</b><small>${esc(x.path)}</small></span><span class="config-file-meta"><em>${esc(x.category||x.family)}</em><small>${x.kind==='vhost'?'Advanced vhost':esc(x.service||'')}</small></span></button>`).join(''):'<div class="empty">No configuration files match this view.</div>';
}
async function refreshConfigFiles(){const root=$('configFilesTable');if(!root)return;try{const d=await api('config-files');state.configFiles=d.files||[];renderConfigFiles()}catch(e){root.innerHTML='<div class="empty">Unable to load configuration files.</div>';toast(e.message,true)}}
function configSearchOptions(){return {query:String($('configContentSearch')?.value||''),matchCase:!!$('configContentMatchCase')?.checked}}
function rebuildConfigContentMatches(){
 const ta=$('configFileContent'),count=$('configContentSearchCount'),prev=$('configFindPrev'),next=$('configFindNext'),clear=$('configFindClear'),opts=configSearchOptions();configContentMatches=[];
 if(!ta||ta.disabled){configContentMatchIndex=-1;if(count)count.textContent='Open a file to search';[prev,next,clear].forEach(b=>{if(b)b.disabled=true});return []}
 if(clear)clear.disabled=!opts.query;if(!opts.query){configContentMatchIndex=-1;if(count)count.textContent='Type to search this file';[prev,next].forEach(b=>{if(b)b.disabled=true});return []}
 const source=opts.matchCase?ta.value:ta.value.toLowerCase(),needle=opts.matchCase?opts.query:opts.query.toLowerCase();let at=0;
 while(needle&&at<=source.length-needle.length){const found=source.indexOf(needle,at);if(found<0)break;configContentMatches.push([found,found+needle.length]);at=found+Math.max(needle.length,1)}
 if(configContentMatchIndex>=configContentMatches.length)configContentMatchIndex=configContentMatches.length-1;if(configContentMatchIndex<0&&configContentMatches.length)configContentMatchIndex=0;
 const enabled=configContentMatches.length>0;[prev,next].forEach(b=>{if(b)b.disabled=!enabled});if(count)count.textContent=enabled?`${configContentMatches.length} match${configContentMatches.length===1?'':'es'}`:'No matches';return configContentMatches
}
function revealConfigContentMatch(index,{keepSearchFocus=false}={}){
 const ta=$('configFileContent'),input=$('configContentSearch'),count=$('configContentSearchCount'),matches=rebuildConfigContentMatches();if(!ta||!matches.length)return false;
 configContentMatchIndex=((index%matches.length)+matches.length)%matches.length;const [start,end]=matches[configContentMatchIndex];ta.setSelectionRange(start,end);
 const before=ta.value.slice(0,start),line=before.split('\n').length,lineHeight=parseFloat(getComputedStyle(ta).lineHeight)||18.6;ta.scrollTop=Math.max(0,(line-4)*lineHeight);
 if(count)count.textContent=`${configContentMatchIndex+1} of ${matches.length}`;if(keepSearchFocus&&input)input.focus();else ta.focus({preventScroll:true});return true
}
function resetConfigContentSearch({clearQuery=true}={}){
 const input=$('configContentSearch'),matchCase=$('configContentMatchCase');if(clearQuery&&input)input.value='';configContentMatches=[];configContentMatchIndex=-1;
 const loaded=!!$('configFileContent')&&!$('configFileContent').disabled;if(input)input.disabled=!loaded;if(matchCase)matchCase.disabled=!loaded;rebuildConfigContentMatches()
}
async function openConfigFile(id){try{const d=await api('config-read&id='+encodeURIComponent(id)),f=d.file||{};$('configFileId').value=f.id||id;$('configFileSha').value=f.sha256||'';$('configFilePath').textContent=f.path||'—';$('configFileContent').value=d.content||'';$('configFileContent').disabled=false;$('configEditorTitle').textContent=f.label||'Configuration editor';$('configEditorCategory').textContent=String(f.category||f.family||'CONFIGURATION').toUpperCase();$('configEditorDescription').textContent=f.description||'Approved Privora configuration file.';$('configEditorService').textContent='SERVICE '+String(f.service||'—').toUpperCase();$('configEditorService').className='status-pill active';$('configEditorKind').textContent=f.kind==='vhost'?'ADVANCED VHOST':'COMMON / CORE';$('configEditorKind').className='status-pill '+(f.kind==='vhost'?'warning':'active');const save=$('configEditorForm')?.querySelector('button[type="submit"]');if(save)save.disabled=false;resetConfigContentSearch({clearQuery:true});renderConfigFiles();$('configFileContent').focus()}catch(e){toast(e.message,true)}}
function componentMatches(c,q){const hay=[c.name,c.id,c.category,c.description,...(c.packages||[]),...(c.tags||[])].join(' ').toLowerCase();return !q||hay.includes(q)}
function componentFilteredRows(){const q=String($('componentSearch')?.value||'').trim().toLowerCase();return state.components.filter(c=>{const catOK=componentCategory==='all'||(componentCategory==='installed'?c.installed:c.category===componentCategory);return catOK&&componentMatches(c,q)})}
function syncComponentFilterUI(){document.querySelectorAll('#componentCategoryTabs [data-component-category]').forEach(b=>{const active=(b.dataset.componentCategory||'all')===componentCategory;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false')});const count=$('componentResultCount'),q=String($('componentSearch')?.value||'').trim();if(count){const n=componentFilteredRows().length;count.textContent=`Showing ${n} of ${state.components.length} component${state.components.length===1?'':'s'}${q?` · search “${q}”`:''}`}}
function renderComponents(){const root=$('componentCatalog');if(!root)return;const rows=componentFilteredRows();syncComponentFilterUI();if(!rows.length){root.innerHTML='<article class="panel-card"><div class="empty">No components match the selected category and search.</div></article>';return}const groups=[];for(const c of rows){let g=groups.find(x=>x.name===c.category);if(!g){g={name:c.category,rows:[]};groups.push(g)}g.rows.push(c)}root.innerHTML=groups.map(g=>`<section class="component-group"><div class="component-group-head"><div><h3>${esc(g.name)}</h3></div><small>${g.rows.length} component${g.rows.length===1?'':'s'}</small></div><div class="component-grid">${g.rows.map(c=>{const cls=c.installed?'installed':c.partial?'partial':c.available?'available':'unsupported',label=c.installed?'Installed':c.partial?'Partial':c.available?'Available':'Not supported',action=c.installed?(c.removable?`<button class="ghost component-remove" type="button" data-component-remove="${esc(c.id)}">Remove</button>`:`<button class="ghost" type="button" disabled>Installed</button>`):(c.available?`<button class="primary" type="button" data-component-install="${esc(c.id)}">${c.partial?'Complete install':'Install'}</button>`:`<button class="ghost" type="button" disabled>Unavailable</button>`);return `<article class="panel-card component-card ${c.featured?'featured':''}"><div class="component-card-head"><div><h4>${esc(c.name)}</h4><span>${esc(c.category)}</span></div><em class="status-pill ${cls==='installed'?'active':cls==='partial'?'warning':cls==='available'?'sim':'failed'}">${label}</em></div><p>${esc(c.description||'')}</p><div class="component-packages"><span>Packages</span><code>${esc((c.packages||[]).join(' · ')||'internal')}</code></div>${c.version?`<small class="component-version">Installed version ${esc(c.version)}</small>`:''}<div class="component-card-footer"><small>${esc(c.status_reason||'')}</small>${action}</div></article>`}).join('')}</div></section>`).join('')}
function setComponentCategory(category){componentCategory=category||'all';renderComponents();$('componentCatalog')?.scrollIntoView({block:'start',behavior:'smooth'})}
function clearComponentFilters(){componentCategory='all';if($('componentSearch'))$('componentSearch').value='';renderComponents()}
function softwareProgressMarkup(key){const job=softwareJobState[key];if(!job)return '';const value=Math.max(0,Math.min(100,Number(job.progress||0))),failed=job.status==='failed',label=failed?(job.error||job.message||'Install failed'):(job.message||job.phase||'Working…');return `<div class="component-job-progress ${failed?'failed':''}"><div class="component-job-progress-head"><span>${esc(String(job.phase||job.status||'working').replaceAll('-',' '))}</span><strong>${value}%</strong></div><progress class="component-progress-track" max="100" value="${value}" aria-label="Software installation progress"></progress><small>${esc(label)}</small></div>`}
async function startPanelSoftwareJob(kind,action,target,phpVersion=''){const r=await api('software-job-start',{method:'POST',data:{kind,action,target,php_version:phpVersion}});if(!r.job?.id)throw new Error('Privora did not return a software job ID.');return r.job}
async function pollPanelSoftwareJob(job,key,onUpdate){let misses=0;while(job&&['queued','running'].includes(job.status)){await new Promise(r=>setTimeout(r,850));try{const d=await api('software-job-status&id='+encodeURIComponent(job.id));job=d.job||job;softwareJobState[key]=job;misses=0;onUpdate?.()}catch(err){misses++;if(misses>=3){const j=softwareJobState[key];if(j)j.message='Install still running · status retry';onUpdate?.()}if(misses>20)throw new Error('Install is still running but progress status is temporarily unavailable. Refresh this page to reconnect.')}}return job}
function renderSoftwarePresets(){const root=$('softwarePresetList');if(!root)return;root.innerHTML=(state.componentPresets||[]).map(p=>{const key='preset:'+p.id,job=softwareJobState[key],busy=job&&['queued','running'].includes(job.status);return `<article class="panel-card component-card preset-card" data-preset-card="${esc(p.id)}"><div class="component-card-head"><div><h4>${esc(p.name)}</h4><span>PHP ${esc(p.php_version)}</span></div><em class="status-pill ${p.ready?'active':'failed'}">${p.ready?'READY':'BLOCKED'}</em></div><p>${esc(p.description||'')}</p><div class="preset-lines"><small><b>Already installed:</b> ${esc((p.already_installed||[]).join(', ')||'none')}</small><small><b>Will install:</b> ${esc((p.will_install||[]).join(', ')||'nothing')}</small><small><b>Unavailable:</b> ${esc((p.unavailable||[]).join(', ')||'none')}</small><small><b>Requires restart:</b> ${esc((p.requires_restart||[]).join(', ')||'none')}</small></div>${softwareProgressMarkup(key)}<button class="primary preset-apply" data-preset-apply="${esc(p.id)}" ${p.ready&&!busy?'':'disabled'}>${busy?'Installing…':(p.will_install||[]).length?'Apply preset':'Already satisfied'}</button></article>`}).join('')||'<div class="empty">No presets available.</div>'}
function renderPHPVersionCatalog(){const rows=(state.phpVersions||[]).map(v=>[`${esc(v.version)}${v.protected?' <span class="badge">PROTECTED</span>':''}`,v.installed?'<em class="status-pill active">Installed</em>':v.available?'<em class="status-pill sim">Available</em>':'<em class="status-pill failed">Unavailable</em>',v.fpm?`${v.fpm_active?'FPM active':'FPM installed'}`:'No FPM',v.installed?(v.protected?'<button class="ghost" disabled>Protected</button>':`<button class="ghost php-version-remove" data-php-version="${esc(v.version)}">Remove</button>`):(v.available?`<button class="primary php-version-install" data-php-version="${esc(v.version)}">Install</button>`:'—')]);simpleTable('phpVersionCatalog',['Version','Status','FPM','Action'],rows)}
function renderPHPExtensionMatrix(){const version=$('phpExtensionVersion')?.value||'8.4',rows=(state.phpExtensions||[]).filter(e=>e.version===version).map(e=>{const action=e.source==='package'?(e.installed?(e.removable?`<button class="ghost" type="button" data-component-remove="${esc(e.id)}">Remove</button>`:'—'):(e.available?`<button class="primary" type="button" data-component-install="${esc(e.id)}">Install</button>`:'—')):'Bundled';return [esc(e.name),esc(e.module),e.installed?'<em class="status-pill active">Installed</em>':e.available?'<em class="status-pill sim">Available</em>':`<em class="status-pill ${e.source==='bundled'?'warning':'failed'}">${esc(e.status)}</em>`,esc(e.package||'Bundled with PHP'),esc(e.status_reason||''),action]});simpleTable('phpExtensionMatrix',['Extension','Module','Status','Package','Detail','Action'],rows)}
async function refreshSmartPresets(){const root=$('softwarePresetList');if(!root)return;const version=$('softwarePresetPHP')?.value||'8.4';root.innerHTML='<div class="empty">Refreshing smart presets…</div>';try{const [p,j]=await Promise.all([api('component-presets&php_version='+encodeURIComponent(version)),api('software-jobs').catch(()=>({jobs:[]}))]);state.componentPresets=p.presets||[];for(const job of (j.jobs||[])){if(job.kind==='preset'&&['queued','running'].includes(job.status))softwareJobState['preset:'+job.target]=job}renderSoftwarePresets()}catch(err){root.innerHTML='<div class="empty">Smart preset inventory unavailable.</div>';toast(err.message,true)}}
async function refreshPHPInventory(){if(!$('phpVersionCatalog')&&!$('phpExtensionMatrix'))return;try{const [v,e]=await Promise.all([api('php-versions'),api('php-extensions')]);state.phpVersions=v.versions||[];state.phpExtensions=e.extensions||[];renderPHPVersionCatalog();renderPHPExtensionMatrix()}catch(err){if($('phpVersionCatalog'))$('phpVersionCatalog').innerHTML='<div class="empty">PHP runtime inventory unavailable.</div>';if($('phpExtensionMatrix'))$('phpExtensionMatrix').innerHTML='<div class="empty">PHP extension inventory unavailable.</div>';toast(err.message,true)}}
async function refreshComponents(){const root=$('componentCatalog');if(!root)return;root.innerHTML='<article class="panel-card"><div class="empty">Refreshing package inventory…</div></article>';try{const d=await api('components');state.components=d.components||[];const counts=d.counts||{};$('componentInstalledCount').textContent=counts.installed??state.components.filter(x=>x.installed).length;$('componentAvailableCount').textContent=counts.available??state.components.filter(x=>x.available&&!x.installed).length;$('componentTotalCount').textContent=counts.total??state.components.length;renderComponents();await refreshPHPInventory()}catch(e){root.innerHTML='<article class="panel-card"><div class="empty">Unable to load component inventory.</div></article>';toast(e.message,true)}}
function nsCheck(ok,yes,no){return `<span class="ns-check ${ok?'ok':'bad'}"><b>${ok?'✓':'✗'}</b> ${esc(ok?yes:no)}</span>`}
function renderNameserverSetup(rows,reg){const root=$('nameserverSetup');if(!root)return;root.innerHTML=rows.length?rows.map(x=>`<article class="nameserver-setup-card"><div class="card-head"><div><span class="eyebrow">NAMESERVER SETUP</span><h3>${esc(x.base_domain)}</h3></div>${x.delegation_active&&x.glue_registered?'<span class="status-pill active">PUBLIC DNS READY</span>':x.dns_zone_configured&&x.nameserver_service_running?'<span class="status-pill warning">LOCAL DNS READY · REGISTRAR PENDING</span>':'<span class="status-pill failed">SETUP INCOMPLETE</span>'}</div><div class="ns-host-grid"><span><b>${esc(x.primary)}</b><small>Primary nameserver</small></span><code>${esc(x.ipv4||x.ipv6||'No public address')}</code><span><b>${esc(x.secondary)}</b><small>Secondary nameserver</small></span><code>${esc(x.ipv4||x.ipv6||'No public address')}</code></div><div class="ns-health-list"><div><span>DNS zone:</span>${nsCheck(!!x.dns_zone_configured,'Configured','Not configured')}</div><div><span>Nameserver service:</span>${nsCheck(!!x.nameserver_service_running,'Running','Not running')}</div><div><span>Glue records:</span>${nsCheck(!!x.glue_registered,'Registered','Not registered')}</div><div><span>Delegation:</span>${nsCheck(!!x.delegation_active,'Active','Not active')}</div></div>${x.detail?`<p class="muted">${esc(x.detail)}</p>`:''}<div class="ns-setup-actions"><button class="primary" type="button" data-registrar-connect="${esc(x.base_domain)}">${reg.connected?'Registrar Connected':'Connect Registrar'}</button><button class="ghost" type="button" data-nameserver-manual="${esc(x.base_domain)}">Show Manual Instructions</button></div></article>`).join(''):'<div class="empty">Create a nameserver set to see registry glue and delegation status.</div>'}
async function refreshNameservers(){const box=$('nameserverStatus');if(!box)return;try{const d=await api('nameservers'),sets=d.nameserver_sets||[],setup=d.setup_status||[],reg=d.registrar||{},assign=d.assignments||{},form=$('nameserverForm');state.nameserverSets=sets;state.nameserverSetup=setup;state.nameserverAssignments=assign;if(form){if(!form.elements.ipv4.value)form.elements.ipv4.value=d.detected_ipv4||'';if(!form.elements.ipv6.value)form.elements.ipv6.value=d.detected_ipv6||'';if(sets.length===0&&form.elements.default)form.elements.default.checked=true}const as=$('nameserverAssignmentSet');if(as){as.innerHTML=sets.map(x=>`<option value="${esc(x.base_domain)}">${esc(x.primary)} / ${esc(x.secondary)}${x.default?' — default':''}</option>`).join('')}const glueLabel=x=>x.glue_status==='registrar-glue-synced'?'REGISTRAR GLUE SYNCED':x.glue_status==='registrar-sync-failed'?'REGISTRAR SYNC FAILED':'LOCAL GLUE READY';box.innerHTML=sets.length?`<div class="tr th nameserver-set-tr"><span>Base domain</span><span>Nameservers</span><span>Address</span><span>Status</span><span>Actions</span></div>`+sets.map(x=>`<div class="tr nameserver-set-tr"><span><b>${esc(x.base_domain)}</b>${x.default?'<small>Default for unassigned zones</small>':''}</span><span><b>${esc(x.primary)}</b><small>${esc(x.secondary)}</small></span><span>${esc(x.ipv4||x.ipv6||'—')}</span><span><em class="status-pill ${x.glue_status==='registrar-sync-failed'?'failed':'active'}">${esc(glueLabel(x))}</em></span><span class="row-actions"><button class="table-btn" data-nameserver-edit="${esc(x.base_domain)}">Edit</button><button class="danger nameserver-delete-btn" data-nameserver-delete="${esc(x.base_domain)}">Delete set</button></span></div>`).join(''):'<div class="empty">No Privora nameserver sets configured yet.</div>';const ar=$('nameserverAssignments');if(ar){const rows=Object.entries(assign);ar.innerHTML=rows.length?`<div class="tr th"><span>Hosted domain</span><span>Assigned set</span><span>Published nameservers</span></div>`+rows.map(([domain,base])=>{const x=sets.find(v=>v.base_domain===base);return `<div class="tr"><span><b>${esc(domain)}</b></span><span>${esc(base)}</span><span>${x?esc(x.primary)+'<small>'+esc(x.secondary)+'</small>':'<em class="status-pill failed">MISSING SET</em>'}</span></div>`}).join(''):'<div class="empty">No explicit assignments. Hosted root domains use the default set.</div>'}$('nameserverRegistrarNote').textContent=d.registrar_note||'';const rs=$('registrarStatus');if(rs)rs.innerHTML=reg.connected?`<span class="status-pill active">Registrar adapter connected${reg.provider?' · '+esc(reg.provider):''}</span>`:`<span class="status-pill warning">Registrar connection required for registry glue/delegation</span>`;renderNameserverSetup(setup,reg)}catch(e){toast(e.message,true)}}

