async function refreshUpdates(){const results=await Promise.allSettled([api('updates'),api('update-center')]),pkg=results[0],core=results[1],d=pkg.status==='fulfilled'?pkg.value:null,coreErr=core.status==='rejected'?String(core.reason?.message||core.reason):'',c=core.status==='fulfilled'?core.value:(d?{version:d.version||'5.0.0-dev.6.75',policy:{channel:'developer',security_auto:false,package_auto:false,major_versions_manual:true,auto_reboot:false,reboot_window:'Sun 03:00'},last_transaction:null,degraded:true,status_error:coreErr||'Core status endpoint unavailable',root_reauth_available:false,mfa_required:false}:null);state.updates={packages:d||{},center:c||{},errors:{packages:pkg.status==='rejected'?String(pkg.reason?.message||pkg.reason):'',center:coreErr}};if(d){$('updatesCount').textContent=d.count??0;$('securityUpdates').textContent=d.security??0;$('rebootRequired').textContent=d.reboot_required?'Yes':'No';const rows=d.packages||[];$('updatesTable').innerHTML=`<div class="tr th"><span>Package</span><span>Installed</span><span>Available</span><span>Type</span></div>`+rows.map(p=>`<div class="tr"><span><b>${esc(p.name)}</b></span><span>${esc(p.current)}</span><span>${esc(p.available)}</span><span><em class="status-pill ${p.type==='security'?'security':'normal'}">${esc(p.type)}</em></span></div>`).join('')}else{$('updatesCount').textContent='ERR';$('securityUpdates').textContent='ERR';$('updatesTable').innerHTML=`<div class="empty"><b>System package inventory unavailable.</b><br>${esc(state.updates.errors.packages||'Unknown error')}</div>`}if(c){const cv=$('updateCurrentVersion');if(cv)cv.textContent=c.version||d?.version||'—';const rb=$('updateReauthBadge');if(rb){rb.textContent=c.degraded?'CORE STATUS DEGRADED':(c.root_reauth_available?'ROOT REAUTH READY':'ROOT REAUTH UNAVAILABLE');rb.className='status-pill '+(c.degraded?'warning':(c.root_reauth_available?'active':'failed'))}const mw=$('updateMfaWrap');if(mw)mw.hidden=!c.mfa_required;const pol=c.policy||{},f=$('updatePolicyForm');if(f){f.elements.channel.value=pol.channel||'stable';f.elements.security_auto.checked=!!pol.security_auto;f.elements.package_auto.checked=!!pol.package_auto;f.elements.major_versions_manual.checked=pol.major_versions_manual!==false;f.elements.auto_reboot.checked=!!pol.auto_reboot;f.elements.reboot_window.value=pol.reboot_window||'Sun 03:00'}const tx=c.last_transaction||null;$('updateLastStatus').textContent=tx?.status?String(tx.status).toUpperCase():'NONE';$('updateLastVersion').textContent=tx?.new_version||tx?.old_version||'none yet';$('updateTxn').textContent=tx?`Transaction ${tx.id||'latest'} · ${tx.phase||'unknown'} · ${tx.status||'unknown'}${tx.backup_path?' · backup '+tx.backup_path:''}${c.degraded&&c.status_error?' · status fallback: '+c.status_error:''}`:(c.degraded?'Core status is running in local fallback mode: '+(c.status_error||'agent status temporarily unavailable'):'No update transaction has run on this server yet.');if(tx?.id&&String(tx.status||'').toLowerCase()==='running'){updateProgress(tx);if(updatePollingId!==tx.id)pollUpdateTransaction(tx.id)}}else{const rb=$('updateReauthBadge');if(rb){rb.textContent='CORE STATUS UNAVAILABLE';rb.className='status-pill failed'}$('updateTxn').textContent='Core updater status unavailable: '+(state.updates.errors.center||'Unknown error')}$('updateCurrentVersion').textContent=c?.version||d?.version||'—';if(pkg.status==='rejected')toast('System package inventory unavailable: '+state.updates.errors.packages,true);if(core.status==='rejected'&&!c)toast('Core updater status unavailable: '+state.updates.errors.center,true);renderDashboardGuidance()}

async function refreshResources(){try{renderResources(await api('resources-all'))}catch(e){toast(e.message,true)}}
function simpleTable(id,headers,rows){const roots=[...document.querySelectorAll(`[id="${id}"]`)];if(!roots.length)return;const html=`<div class="tr th resource-tr">${headers.map(h=>`<span>${esc(h)}</span>`).join('')}</div>`+(rows.length?rows.map(r=>`<div class="tr resource-tr">${r.map(v=>`<span>${v}</span>`).join('')}</div>`).join(''):'<div class="empty">No resources yet.</div>');roots.forEach(root=>root.innerHTML=html)}
function renderAdminDatabaseEngines(d){const engines=d.host_capabilities?.database_engines||[],map=new Map(engines.map(x=>[x.engine,x])),labels={mysql:'MySQL',mariadb:'MariaDB',postgresql:'PostgreSQL'},sel=$('adminDatabaseEngine');if(sel){const previous=sel.value;sel.innerHTML='';['mysql','mariadb','postgresql'].forEach(name=>{const c=map.get(name),o=document.createElement('option');o.value=name;o.textContent=labels[name]+((c&&c.available&&c.certified)?'':' — unavailable');o.disabled=!(c&&c.available&&c.certified);sel.appendChild(o)});const usable=[...sel.options].find(o=>!o.disabled);if(previous&&[...sel.options].some(o=>o.value===previous&&!o.disabled))sel.value=previous;else if(usable)sel.value=usable.value}const hint=$('adminDatabaseEngineHint');if(hint){const usable=engines.filter(x=>x.available&&x.certified).map(x=>labels[x.engine]||x.engine);hint.textContent=usable.length?'Certified on this VPS: '+usable.join(', '):'No certified SQL engine is currently available.'}}
