 simpleTable('appsTable',['Type','Domain','Owner','Status'],(d.applications||[]).map(x=>[`<b>${esc(x.type)}</b>`,esc(x.domain),esc(accountLabel(x.owner)),`<em class="status-pill sim">${esc(x.status)}</em>`]));
 simpleTable('firewallTable',['Direction','Protocol','Port','Action'],(d.firewall_rules||[]).map(x=>[esc(x.direction),esc(x.protocol),String(x.port),`<em class="status-pill sim">${esc(x.action)}</em>`]));
 simpleTable('databasesTable',['Database','Engine','Owner / user','Status / actions'],(d.databases||[]).map(x=>[`<b>${esc(x.name)}</b>`,esc(x.engine),`${esc(x.owner?accountLabel(x.owner):'—')}<small>${x.user?'DB user: '+esc(x.user):''}</small>`,`<em class="status-pill active">${esc(x.status)}</em>${x.managed&&x.user?` <button class="table-btn" data-db-inspect="${esc(x.name)}">Inspect</button> <button class="table-btn" data-db-maint="check" data-db-name="${esc(x.name)}">Check</button> <button class="table-btn" data-db-maint="optimize" data-db-name="${esc(x.name)}">Optimize</button> <button class="table-btn" data-db-export="${esc(x.name)}">Export</button> <button class="table-btn" data-db-import="${esc(x.name)}">Import</button> <button class="table-btn" data-db-manage="${esc(x.name)}">Edit</button> <button class="table-btn" data-db-password="${esc(x.name)}">Set / reset password</button> <button class="table-btn danger" data-db-delete="${esc(x.name)}">Delete</button>`:''}`]));
 renderDNSZones(d.zones||[],d.resource_errors?.zones||'');
 const certs=d.certificates||[];if($('activeCertificateCount'))$('activeCertificateCount').textContent=certs.length;simpleTable('sslTable',['Domain','Issuer','Expires','Days left','Renewal','Status / actions'],certs.map(x=>[`<b>${esc(x.domain)}</b>`,esc(x.provider),x.expires_at?new Date(x.expires_at).toLocaleDateString():'—',Number.isFinite(Number(x.days_remaining))?String(x.days_remaining):'—',`<em class="status-pill ${x.auto_renew?'active':'warning'}">${x.auto_renew?'AUTOMATIC':'MANUAL'}</em>`,`<em class="status-pill ${x.status==='valid'?'active':'failed'}">${esc(String(x.status||'unknown').toUpperCase())}</em> <button class="table-btn" data-ssl-inspect="${esc(x.domain)}">Inspect</button> <button class="table-btn" data-ssl-csr="${esc(x.domain)}">CSR</button> <button class="table-btn" data-ssl-custom="${esc(x.domain)}">Custom</button>${String(x.provider).toLowerCase()==='letsencrypt'?` <button class="table-btn danger" data-ssl-revoke="${esc(x.domain)}">Revoke</button>`:''}`]));refreshAutoSSLDomainSelector();
 simpleTable('backupsTable',['Backup','Scope','Resource','Integrity / action'],(d.backups||[]).map(x=>[`<b>${esc(x.id)}</b><small>${x.sha256?esc(x.sha256.slice(0,12))+'…':'legacy/no digest'}</small>`,esc(x.scope),esc(x.resource),`${x.sha256?'<em class="status-pill active">SHA-256</em>':'<em class="status-pill sim">LEGACY</em>'} ${x.verified_at?'<em class="status-pill active">VERIFIED</em>':''} ${x.sha256?`<button class="table-btn" data-v7-backup-verify="${esc(x.id)}">Verify</button>`:''} ${x.scope==='site'&&x.sha256?`<button class="table-btn danger" data-backup-restore="${esc(x.id)}" data-backup-resource="${esc(x.resource)}">Restore</button>`:''}`]));
 const mailboxes=d.mailboxes||[];if($('mailboxCount'))$('mailboxCount').textContent=mailboxes.length;if($('mailDomainCount'))$('mailDomainCount').textContent=websiteSites().length;simpleTable('mailTable',['Mailbox','Domain','Quota','Status / actions'],mailboxes.map(x=>[`<b>${esc(x.address)}</b><small>Local mailbox</small>`,esc(x.domain),`${Number(x.quota_mb||0).toLocaleString()} MB`,`<em class="status-pill active">${esc(x.status||'active')}</em> <span class="row-actions"><button class="table-btn" type="button" data-mailbox-edit="${esc(x.address)}">Edit</button><button class="table-btn danger" type="button" data-mailbox-delete="${esc(x.address)}">Delete</button></span>`]));
