 const caps=d.host_capabilities?.capabilities||[];simpleTable('advHostCapabilityTable',['Adapter','Dependency','Available','Certified'],caps.map(x=>[`<b>${esc(x.name)}</b>`,esc(x.dependency||'internal'),x.available?'YES':'NO',`<em class="status-pill ${x.certified?'active':'sim'}">${x.certified?'PASS':'GATED'}</em>`]));simpleTable('platformHostCapabilityTable',['Adapter','Dependency','Available','Certified'],caps.map(x=>[`<b>${esc(x.name)}</b>`,esc(x.dependency||'internal'),x.available?'YES':'NO',`<em class="status-pill ${x.certified?'active':'sim'}">${x.certified?'PASS':'GATED'}</em>`]));if($('securityScore'))$('securityScore').textContent=d.security_posture?.score??'—';const securityNames=new Set(['nftables','fail2ban','modsecurity','clamav','openssh-sftp']);simpleTable('securityCapabilityTable',['Control','Dependency','Detected','Certified'],caps.filter(x=>securityNames.has(x.name)).map(x=>[`<b>${esc(x.name)}</b>`,esc(x.dependency||'internal'),x.available?'YES':'NO',`<em class="status-pill ${x.certified?'active':'sim'}">${x.certified?'PASS':'GATED'}</em>`]));const mailNames=new Set(['postfix','dovecot','rspamd','webmail']);simpleTable('mailCapabilityTable',['Component','Dependency','Detected','Certified'],caps.filter(x=>mailNames.has(x.name)).map(x=>[`<b>${esc(x.name)}</b>`,esc(x.dependency||'internal'),x.available?'YES':'NO',`<em class="status-pill ${x.certified?'active':'sim'}">${x.certified?'PASS':'GATED'}</em>`]));const dovecot=caps.find(x=>x.name==='dovecot'),imapBadge=$('imapServiceBadge'),imapStatus=$('imapServiceStatus');if(imapBadge){const ready=!!dovecot?.available&&!!dovecot?.certified;imapBadge.textContent=ready?'IMAP READY':dovecot?.available?'DETECTED':'NOT READY';imapBadge.className='status-pill '+(ready?'active':'warning')}if(imapStatus)imapStatus.textContent=dovecot?.available?`Dovecot detected${dovecot.certified?' and Privora-certified':''}. Secure IMAP uses port 993 with SSL/TLS; plaintext port 143 stays disabled.`:'Dovecot is not currently detected. Use Configure / Repair IMAP to provision the certified mail service.';syncAdminImapHost();const webmail=caps.find(x=>x.name==='webmail');if($('adminWebmailStatus'))$('adminWebmailStatus').innerHTML=webmail?.available?`<em class="status-pill active">WEBMAIL READY</em> ${esc(webmail.client||'Supported client')} · ${webmail.launch_url?`<a href="${esc(webmail.launch_url)}" target="_blank" rel="noopener">Open webmail</a>`:esc(webmail.detail||'route detected')}`:'<em class="status-pill sim">WEBMAIL UNAVAILABLE</em> Install or repair the Privora-certified Roundcube component to enable customer launch.';const pma=caps.find(x=>x.name==='phpmyadmin');if($('phpMyAdminStatus'))$('phpMyAdminStatus').innerHTML=pma?.available&&pma?.certified?`<em class="status-pill active">phpMyAdmin READY</em> Panel-session protected · <a class="table-btn" href="${esc(pma.launch_url||'/phpmyadmin/')}" target="_blank" rel="noopener">Open phpMyAdmin</a>`:'<em class="status-pill sim">phpMyAdmin UNAVAILABLE</em> Install/certify phpMyAdmin before exposing a launch route.';
 const cluster=[...(d.clusters||[]).map(x=>[`<b>${esc(x.name)}</b>`,esc(x.kind),(x.nodes||[]).map(esc).join(', '),esc(x.status)]),...(d.load_balancers||[]).map(x=>[`<b>${esc(x.name)}</b>`,`load-balancer`,(x.backends||[]).map(esc).join(', '),esc(x.status)])];simpleTable('advClusterTable',['Name','Kind','Members','Status'],cluster);simpleTable('platformClusterTable',['Name','Kind','Members','Status'],cluster);
