 const recovery=[...(d.diagnostics||[]).map(x=>[`<b>Diagnostic</b>`,esc(x.scope),esc(x.summary),esc(x.severity)]),...(d.repairs||[]).map(x=>[`<b>Repair</b>`,esc(x.resource),esc(x.action),esc(x.status)])];simpleTable('advRecoveryTable',['Type','Resource','Detail','Status'],recovery);
