async function refreshFiles(){const sel=$('fileAccount');if(!sel||!sel.value){const t=$('filesTable');if(t)t.innerHTML='<div class="empty">Create an active hosting account first.</div>';return}try{const d=await api('files&user='+encodeURIComponent(sel.value)+'&path=.');simpleTable('filesTable',['Name','Type','Size','Mode'],(d.files||[]).map(x=>[`<b>${esc(x.name)}</b>`,esc(x.type),bytes(x.size),esc(x.mode)]))}catch(e){toast(e.message,true)}}
function showSSLOps(title,rows){const root=$('sslOpsResults');if(!root)return;root.innerHTML=`<div class="card-head"><h4>${esc(title)}</h4></div>`+rows.map(([k,v])=>`<div class="data-row"><b>${esc(k)}</b><span><pre>${esc(v)}</pre></span></div>`).join('');root.scrollIntoView({behavior:'smooth',block:'center'})}
document.addEventListener('click',async e=>{const ins=e.target.closest('[data-ssl-inspect]');if(ins){try{const r=await api('ssl-inspect&domain='+encodeURIComponent(ins.dataset.sslInspect)),c=r.certificate||{};showSSLOps(`Certificate · ${c.domain||ins.dataset.sslInspect}`,[['Subject',c.subject||'—'],['Issuer',c.issuer||'—'],['Serial',c.serial||'—'],['Valid from',c.not_before||'—'],['Valid until',c.not_after||'—'],['SANs',c.sans||'—'],['SHA-256',c.fingerprint_sha256||'—']])}catch(err){toast(err.message,true)}return}const csr=e.target.closest('[data-ssl-csr]');if(csr){try{const r=await api('ssl-csr',{method:'POST',data:{domain:csr.dataset.sslCsr}}),x=r.csr||{};showSSLOps(`CSR · ${csr.dataset.sslCsr}`,[['CSR',x.csr||'—'],['CSR path',x.csr_path||'—'],['Private key path',x.private_key_path||'—']]);toast('CSR generated; private key retained securely on the server')}catch(err){toast(err.message,true)}return}const custom=e.target.closest('[data-ssl-custom]');if(custom){$('customCertificateDomain').value=custom.dataset.sslCustom;openModal('customCertificate');return}const rev=e.target.closest('[data-ssl-revoke]');if(rev){const d=rev.dataset.sslRevoke;if(!confirm(`Revoke the Let's Encrypt certificate for ${d}? Privora will immediately restore an HTTP-only vhost.`))return;try{await api('ssl-revoke',{method:'POST',data:{domain:d}});toast(`${d} certificate revoked; HTTPS disabled`);await refreshResources()}catch(err){toast(err.message,true)}}});
function showDatabaseOps(title,rows){const root=$('databaseOpsResults');if(!root)return;root.innerHTML=`<div class="card-head"><h4>${esc(title)}</h4></div>`+rows.map(([k,v])=>`<div class="data-row"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('');root.scrollIntoView({behavior:'smooth',block:'center'})}
document.addEventListener('click',async e=>{const inspect=e.target.closest('[data-db-inspect]');if(inspect){try{const r=await api('database-inspect&name='+encodeURIComponent(inspect.dataset.dbInspect)),i=r.inspection||{};showDatabaseOps(`Inspection · ${i.database||inspect.dataset.dbInspect}`,[['Engine',i.engine||'—'],['Size',bytes(i.size_bytes||0)],['Active connections',String(i.active_connections??0)],['Grants',(i.grants||[]).join(' | ')||'—'],['Slow-query support',i.slow_query_supported?(i.slow_query_enabled?'Enabled':'Supported / disabled'):'Not reported']])}catch(err){toast(err.message,true)}return}const maint=e.target.closest('[data-db-maint]');if(maint){const name=maint.dataset.dbName,action=maint.dataset.dbMaint;if(!confirm(`${action[0].toUpperCase()+action.slice(1)} database ${name}?`))return;try{const r=await api('database-maintenance',{method:'POST',data:{name,action}});showDatabaseOps(`${action} · ${name}`,[['Result','Completed'],['Output',r.output||'No output']]);toast(`${name}: ${action} completed`)}catch(err){toast(err.message,true)}return}const ex=e.target.closest('[data-db-export]');if(ex){try{const r=await api('database-export',{method:'POST',data:{name:ex.dataset.dbExport}}),x=r.export||{};showDatabaseOps(`Export · ${ex.dataset.dbExport}`,[['Path',x.path||'—'],['Size',bytes(x.size_bytes||0)],['Created',x.created_at||'—']]);toast('Database export completed')}catch(err){toast(err.message,true)}return}const im=e.target.closest('[data-db-import]');if(im){const source=prompt('Enter a SQL file path inside the owning hosting account home directory (absolute or home-relative):','');if(!source)return;if(!confirm(`Import ${source} into ${im.dataset.dbImport}? Existing data may be changed.`))return;try{await api('database-import',{method:'POST',data:{name:im.dataset.dbImport,source_path:source}});showDatabaseOps(`Import · ${im.dataset.dbImport}`,[['Source',source],['Result','Completed']]);toast('Database import completed')}catch(err){toast(err.message,true)}}});
$('softwarePresetPHP')?.addEventListener('change',refreshSmartPresets);$('phpExtensionVersion')?.addEventListener('change',renderPHPExtensionMatrix);$('refreshSmartPresets')?.addEventListener('click',refreshSmartPresets);
document.addEventListener('click',async e=>{const pb=e.target.closest('[data-preset-apply]');if(pb){const id=pb.dataset.presetApply,v=$('softwarePresetPHP')?.value||'8.4',p=(state.componentPresets||[]).find(x=>x.id===id),key='preset:'+id;if(!p||!p.ready)return;if(!confirm(`Apply ${p.name} preset for PHP ${v}?\n\nWill install: ${(p.will_install||[]).join(', ')||'nothing'}\nRestarts: ${(p.requires_restart||[]).join(', ')||'none'}`))return;pb.disabled=true;try{let job=await startPanelSoftwareJob('preset','apply',id,v);softwareJobState[key]=job;renderSoftwarePresets();job=await pollPanelSoftwareJob(job,key,renderSoftwarePresets);if(job.status==='failed')throw new Error(job.error||job.message||'Preset failed');toast(`${p.name} preset applied`);delete softwareJobState[key];await Promise.allSettled([refreshSmartPresets(),refreshComponents()])}catch(err){const j=softwareJobState[key];if(j){j.status='failed';j.error=err.message||String(err);renderSoftwarePresets()}toast(err.message,true)}return}const pi=e.target.closest('.php-version-install');if(pi){const v=pi.dataset.phpVersion,key='php:'+v;if(!confirm(`Install PHP ${v} CLI/FPM and required common modules?`))return;pi.disabled=true;try{let job=await startPanelSoftwareJob('php-version','install',v);softwareJobState[key]=job;pi.textContent='Installing…';job=await pollPanelSoftwareJob(job,key,()=>{pi.textContent=`${Number(softwareJobState[key]?.progress||0)}%`});if(job.status==='failed')throw new Error(job.error||job.message||'PHP install failed');toast(`PHP ${v} installed`);delete softwareJobState[key];await refreshComponents()}catch(err){toast(err.message,true)}finally{pi.disabled=false}return}const pr=e.target.closest('.php-version-remove');if(pr){const v=pr.dataset.phpVersion,key='php:'+v;if(!confirm(`Remove PHP ${v}? Privora will refuse if any hosted site still uses it.`))return;pr.disabled=true;try{let job=await startPanelSoftwareJob('php-version','remove',v);softwareJobState[key]=job;pr.textContent='Removing…';job=await pollPanelSoftwareJob(job,key,()=>{pr.textContent=`${Number(softwareJobState[key]?.progress||0)}%`});if(job.status==='failed')throw new Error(job.error||job.message||'PHP removal failed');toast(`PHP ${v} removed`);delete softwareJobState[key];await refreshComponents()}catch(err){toast(err.message,true)}finally{pr.disabled=false}}});
$('customCertificateForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries());try{await api('ssl-custom-install',{method:'POST',data:d});closeModal(f);f.reset();toast(`Custom certificate installed for ${d.domain}`);await refreshResources()}catch(err){toast(err.message,true)}});
const titles={dashboard:'Server overview',settings:'Panel preferences & security',components:'Extensions & components',presets:'Smart presets',packages:'Packages',features:'Feature Manager',serveradmin:'Server administration',transfers:'Migration / Transfer Tool',developer:'API, hooks & plugins',cluster:'DNS cluster & multi-server',services:'Service control',config:'Config editor',updates:'System updates',accounts:'Hosting accounts',websites:'Websites',files:'Files',sftp:'SFTP accounts',apps:'Application deployments',php:'PHP manager',databases:'Databases',dns:'DNS zones',nameservers:'Nameservers',ssl:'SSL certificates',backups:'Backups',mail:'Mail Center',resellers:'Reseller Center',firewall:'Firewall Manager',security:'Security center',operations:'Operations & monitoring',platform:'Platform Labs & Engineering'};
function navigate(page){document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.dataset.view===page));document.querySelectorAll('.nav-link').forEach(e=>e.classList.toggle('active',e.dataset.page===page));const activeNav=document.querySelector(`.nav-link[data-page="${CSS.escape(page)}"]`),activeGroup=activeNav?.closest('.nav-group');if(activeGroup)activeGroup.open=true;$('pageTitle').textContent=titles[page]||'Privora Panel';if(page==='updates')refreshUpdates();if(page==='config')refreshConfigFiles();if(page==='components')refreshComponents();if(page==='presets')refreshSmartPresets();if(page==='nameservers')refreshNameservers();if(page==='settings')refreshAdminMfa();if(['accounts','websites','files','php','services'].includes(page)){refresh().then?.(()=>{});if(page==='files')setTimeout(refreshFiles,80);}if(['accounts','packages','features','resellers'].includes(page))refreshPackages();if(['php','sftp','apps','databases','dns','ssl','backups','mail','resellers','firewall','platform'].includes(page))refreshResources();if(['operations','platform','serveradmin','transfers','developer','cluster','security','mail','databases'].includes(page))refreshAdvanced();history.replaceState(null,'','#'+page)}

