const updatePhasePercent={launch:2,preflight:8,backup:18,release:32,dependencies:43,stage:53,migrations:63,validate:72,promote:80,restart:89,health:96,complete:100,rollback:100};
const updatePhaseLabels={launch:'Launch worker',preflight:'Preflight',backup:'Snapshot',release:'Verify package',dependencies:'Dependencies',stage:'Stage release',migrations:'Migrations',validate:'Validate',promote:'Promote',restart:'Restart services',health:'Health checks',complete:'Complete',rollback:'Rollback'};
const updatePhaseOrder=['launch','preflight','backup','release','dependencies','stage','migrations','validate','promote','restart','health','complete'];
const updateStallAfter={preflight:90,backup:300,release:180,dependencies:300,stage:180,migrations:300,validate:180,promote:90,restart:120,health:120,rollback:180};
let lastUpdateTx=null,updateProgressTimer=null;
function parseTime(v){if(!v)return null;const d=new Date(v);return Number.isFinite(d.getTime())?d:null}
function secondsSince(v){const d=parseTime(v);return d?Math.max(0,Math.floor((Date.now()-d.getTime())/1000)):0}
function fmtDuration(sec){sec=Math.max(0,Math.floor(Number(sec)||0));if(sec<60)return `${sec}s`;const m=Math.floor(sec/60),s=sec%60;if(m<60)return `${m}m ${s}s`;const h=Math.floor(m/60);return `${h}h ${m%60}m`}
function renderUpdateStages(phase,status,failedPhase=''){const box=$('updateStageList');if(!box)return;const shownFailure=failedPhase||((status==='failed')?phase:''),fi=updatePhaseOrder.indexOf(shownFailure),pi=updatePhaseOrder.indexOf(phase);box.innerHTML=updatePhaseOrder.map((p,i)=>{let c='pending',icon='○';if(status==='pass'||(fi>=0&&i<fi)||(!shownFailure&&pi>=0&&i<pi)){c='done';icon='✓'}if(status==='running'&&p===phase){c='current';icon='●'}if(shownFailure&&p===shownFailure){c='failed';icon='✕'}if(p==='complete'&&status==='pass'){c='done';icon='✓'}return `<span class="${c}"><i>${icon}</i>${esc(updatePhaseLabels[p]||p)}</span>`}).join('')}
function refreshUpdateClock(){const tx=lastUpdateTx;if(!tx)return;const status=String(tx.status||'running').toLowerCase(),phase=String(tx.phase||'starting').toLowerCase();const total=secondsSince(tx.started_at||tx.updated_at),stage=secondsSince(tx.phase_started_at||tx.updated_at),activity=secondsSince(tx.activity_at||tx.updated_at);const e=$('updateProgressElapsed'),se=$('updateStageElapsed'),la=$('updateLastActivity');if(e)e.textContent=fmtDuration(total);if(se)se.textContent=fmtDuration(stage);if(la)la.textContent=activity<3?'now':`${fmtDuration(activity)} ago`;const warning=$('updateStallWarning'),text=$('updateStallText'),limit=updateStallAfter[phase]||180,isRunning=status==='running',slow=isRunning&&stage>limit;if(warning)warning.hidden=!slow;if(text&&slow)text.textContent=`${updatePhaseLabels[phase]||phase} has been running for ${fmtDuration(stage)}. Expected alert threshold: ${fmtDuration(limit)}. The updater is still being polled; review the current operation before interrupting it.`;const badge=$('updateProgressStatus');if(badge&&slow){badge.textContent='SLOW / CHECK';badge.className='status-pill warning'}}
function ensureUpdateClock(){if(updateProgressTimer)return;updateProgressTimer=setInterval(refreshUpdateClock,1000)}
function setUpdateReview(u){pendingCoreUpdate=u;const box=$('updatePackageReview');if(!box)return;$('reviewVersion').textContent=u.version||'—';$('reviewChannel').textContent=u.channel||'—';$('reviewSha').textContent=u.zip_sha256||'—';const bits=[];if((u.services||[]).length)bits.push('Services: '+u.services.join(', '));if((u.migrations||[]).length)bits.push('Migrations: '+u.migrations.join(', '));bits.push(`Package ${(Number(u.size_bytes||0)/1048576).toFixed(1)} MB · payload signature verified`);$('reviewChanges').textContent=bits.join(' · ');box.hidden=false;const pw=$('updateRootPassword'),mc=$('updateMfaCode');if(pw){pw.value='';setTimeout(()=>pw.focus(),40)}if(mc)mc.value=''}
async function postUpdateZip(form){const csrf=csrfToken();if(!csrf)throw new Error('Security token missing. Reload Privora and try again.');const fd=new FormData(form);const url=new URL('api.php',document.baseURI);url.searchParams.set('route','update-upload-prepare');const r=await fetch(url,{method:'POST',headers:{'Accept':'application/json','X-CSRF-Token':csrf},credentials:'same-origin',cache:'no-store',body:fd});const j=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok)throw new Error(j.error||'Update package upload failed');return j}
$('updateUploadForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,file=$('updateZip')?.files?.[0];if(!file){toast('Choose a Privora update ZIP',true);return}if(/full[-_ ]?core/i.test(file.name)){toast('That is a Privora fresh-install full-core archive, not an Update Center package. Choose the signed *-update.zip file instead.',true);return;}const b=$('validateUpdateZip');b.disabled=true;pendingCoreUpdate=null;$('updatePackageReview').hidden=true;try{const j=await postUpdateZip(f);setUpdateReview(j.upload||{});f.reset();toast(`Privora ${j.upload?.version||'package'} signature verified`)}catch(err){toast(err.message,true)}finally{b.disabled=false}});
function updateProgress(tx){const box=$('updateProgress');if(!box)return;box.hidden=false;lastUpdateTx=tx||{};ensureUpdateClock();const status=String(tx.status||'running').toLowerCase(),phase=String(tx.phase||'starting').toLowerCase(),failedPhase=String(tx.failed_phase||'').toLowerCase();box.classList.toggle('update-success',status==='pass');box.classList.toggle('update-failure',status==='failed'||status==='rolled-back');const percent=status==='rolled-back'&&failedPhase?(updatePhasePercent[failedPhase]||100):(updatePhasePercent[phase]||12);$('updateProgressTitle').textContent=status==='pass'?'Update complete':status==='rolled-back'?'Update rolled back after failure':status==='failed'?'Update failed':`Installing ${pendingCoreUpdate?.version||tx.new_version||'Privora'}`;const badge=$('updateProgressStatus');badge.textContent=status==='pass'?'SUCCESS':status==='rolled-back'?'ROLLED BACK':status.toUpperCase();badge.className='status-pill '+(status==='pass'?'success':(status==='failed'||status==='rolled-back'?'failed':'active'));$('updateProgressBar').style.width=percent+'%';$('updateProgressBar').className=status==='pass'?'success':(status==='failed'||status==='rolled-back'?'failed':'');const pct=$('updateProgressPercent');if(pct)pct.textContent=percent+'%';const detail=$('updateProgressDetail');if(status==='rolled-back'||status==='failed'){const fp=failedPhase||phase,fo=tx.failed_operation||tx.operation||'',fe=tx.failed_error||tx.error||'',frc=tx.failed_rc?`rc=${tx.failed_rc}`:'';detail.textContent=`${status==='rolled-back'?'Rollback after':'Failed at'} ${updatePhaseLabels[fp]||fp}${fo?' · '+fo:''}${frc?' · '+frc:''}${fe?' · '+fe:''}`;detail.className='update-progress-detail failure'}else if(status==='pass'){detail.textContent='Success: all update stages and post-update health checks passed.';detail.className='update-progress-detail success'}else{const op=tx.operation?` · ${tx.operation}`:'';detail.textContent=`Current stage: ${updatePhaseLabels[phase]||phase}${op}`;detail.className='update-progress-detail'}renderUpdateStages(phase,status,failedPhase);refreshUpdateClock();}
async function pollUpdateTransaction(id){if(updatePollingId===id)return;updatePollingId=id;let misses=0;for(let i=0;i<900;i++){await new Promise(r=>setTimeout(r,2000));try{const j=await api('update-status&id='+encodeURIComponent(id)),tx=j.transaction||{};misses=0;updateProgress(tx);if(['pass','failed','rolled-back'].includes(String(tx.status||'').toLowerCase())){await refreshUpdates().catch(()=>{});if(String(tx.status).toLowerCase()==='pass'){toast('Privora update installed successfully');setTimeout(()=>location.reload(),1800)}else{const detail=[tx.failed_phase?`failed at ${updatePhaseLabels[String(tx.failed_phase).toLowerCase()]||tx.failed_phase}`:'',tx.failed_operation||tx.operation,tx.failed_error||tx.error].filter(Boolean).join(' · ');toast(`Update ${tx.status}${detail?': '+detail:'. Previous release is protected.'}`,true)}updatePollingId=null;return}}catch(err){misses++;const badge=$('updateProgressStatus');if(badge&&misses>=3){badge.textContent='STATUS RETRY';badge.className='status-pill warning'}if(misses>20){toast('Updater status is temporarily unavailable. Refresh Update Center to check the transaction.',true);updatePollingId=null;return}}}updatePollingId=null}
