const PREF_KEY='privora.admin.preferences.v1';
const adminPrefDefaults={theme:'dark',density:'comfortable',sidebar:'remember',landing:'dashboard',table_density:'standard',motion:'normal'};
function readAdminPrefs(){try{return {...adminPrefDefaults,...JSON.parse(localStorage.getItem(PREF_KEY)||'{}')}}catch(_){return {...adminPrefDefaults}}}
function resolvedTheme(v){if(v!=='system')return v;return matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'}
function applyAdminPrefs(prefs=readAdminPrefs()){
  document.body.classList.toggle('ui-theme-light',resolvedTheme(prefs.theme)==='light');
  document.body.classList.toggle('ui-density-compact',prefs.density==='compact');
  document.body.classList.toggle('ui-table-compact',prefs.table_density==='compact');
  document.body.classList.toggle('ui-motion-reduced',prefs.motion==='reduced');
  document.querySelectorAll('.sidebar .nav-group').forEach(d=>{
    if(prefs.sidebar==='expanded')d.open=true;
    else if(prefs.sidebar==='collapsed')d.open=!!d.querySelector('.nav-link.active');
  });
}
function syncAdminPreferenceForm(){const f=$('panelPreferencesForm'),p=readAdminPrefs();if(!f)return;for(const [k,v] of Object.entries(p))if(f.elements[k])f.elements[k].value=v}
function enhanceSidebarNavigation(){
  const nav=document.querySelector('.sidebar nav');if(!nav||nav.dataset.grouped==='1')return;nav.dataset.grouped='1';
  const nodes=[...nav.children];
  for(let i=0;i<nodes.length;i++){
    const label=nodes[i];if(label.tagName!=='P')continue;
    const details=document.createElement('details');details.className='nav-group';details.dataset.group=label.textContent.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-');
    const summary=document.createElement('summary');summary.innerHTML=`<span>${esc(label.textContent.trim())}</span><i>⌄</i>`;details.appendChild(summary);nav.insertBefore(details,label);label.remove();
    for(let j=i+1;j<nodes.length&&nodes[j].tagName!=='P';j++){if(nodes[j].parentNode===nav)details.appendChild(nodes[j])}
    details.open=true;
    summary.addEventListener('click',()=>setTimeout(()=>{const p=readAdminPrefs();if(p.sidebar==='remember'){const states={};document.querySelectorAll('.sidebar .nav-group').forEach(g=>states[g.dataset.group]=g.open);localStorage.setItem('privora.admin.navgroups.v1',JSON.stringify(states))}},0));
  }
  const p=readAdminPrefs();if(p.sidebar==='remember'){try{const st=JSON.parse(localStorage.getItem('privora.admin.navgroups.v1')||'{}');document.querySelectorAll('.sidebar .nav-group').forEach(g=>{if(g.dataset.group in st)g.open=!!st[g.dataset.group]})}catch(_){}}
  document.querySelectorAll('.sidebar .nav-link.active').forEach(b=>{const g=b.closest('.nav-group');if(g)g.open=true});
}
function refreshSitePhpSelectors(){
  const versions=state.phpRuntimes.filter(x=>x.fpm&&(x.switchable||x.fpm_active)).map(x=>String(x.version));
  if(!versions.length)return;
  document.querySelectorAll('#sitePhpVersion,#subdomainForm select[name="php_version"]').forEach(sel=>{const cur=sel.value;sel.innerHTML=versions.map(v=>`<option value="${esc(v)}">PHP ${esc(v)}</option>`).join('');sel.value=versions.includes(cur)?cur:(versions.includes('8.4')?'8.4':versions[0])});
}
function updateSiteProvisionPreview(){const domain=String($('siteDomain')?.value||'').trim().toLowerCase(),owner=String($('siteAccount')?.value||'').trim(),out=$('siteDocumentRootPreview');if(!out)return;out.textContent=domain?(owner?`Managed hosting path · domains/${domain}/public`:`Automatic hosting account · domains/${domain}/public`):'Automatic under hosting account'}
$('siteDomain')?.addEventListener('input',updateSiteProvisionPreview);$('siteAccount')?.addEventListener('change',updateSiteProvisionPreview);
