$('panelPreferencesForm')?.addEventListener('submit',e=>{e.preventDefault();const prefs={...readAdminPrefs(),...Object.fromEntries(new FormData(e.currentTarget))};localStorage.setItem(PREF_KEY,JSON.stringify(prefs));applyAdminPrefs(prefs);toast('Panel preferences saved')});
$('resetPanelPreferences')?.addEventListener('click',()=>{localStorage.removeItem(PREF_KEY);localStorage.removeItem('privora.admin.navgroups.v1');syncAdminPreferenceForm();applyAdminPrefs(adminPrefDefaults);toast('Panel preferences reset')});
