/* 5.0.0-dev.6.85 Rev2 — Mail Center workspace tabs */
function setMailWorkspaceTab(name){
  const wanted=String(name||'mailboxes');
  document.querySelectorAll('[data-mail-tab]').forEach(btn=>{const on=btn.dataset.mailTab===wanted;btn.classList.toggle('active',on);btn.setAttribute('aria-selected',on?'true':'false')});
  document.querySelectorAll('[data-mail-panel]').forEach(panel=>{const on=panel.dataset.mailPanel===wanted;panel.hidden=!on;panel.classList.toggle('active',on)});
  try{localStorage.setItem('privora.mail.tab.v1',wanted)}catch{}
}
function initMailWorkspace(){
  const tabs=[...document.querySelectorAll('[data-mail-tab]')];if(!tabs.length)return;
  let saved='mailboxes';try{saved=localStorage.getItem('privora.mail.tab.v1')||saved}catch{}
  if(!tabs.some(x=>x.dataset.mailTab===saved))saved='mailboxes';setMailWorkspaceTab(saved)
}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-mail-tab]');if(tab){setMailWorkspaceTab(tab.dataset.mailTab)}});
initMailWorkspace();
